def _promote(nodes: list[dict]) -> int:
    end = 0
    for child in nodes:
        if child["nodes"]:
            child["end_index"] = max(child["end_index"], _promote(child["nodes"]))
        end = max(end, child["end_index"])
    return end

def _drop_empty_children(nodes: list[dict]) -> list[dict]:
    for count_item in nodes:
        if count_item["nodes"]:
            _drop_empty_children(count_item["nodes"])
        else:
            del count_item["nodes"]
    return nodes

def build_tree_from_nodes(node_list):
    if not node_list:
        return []

    stack = []
    root_nodes = []
    node_counter = 1

    for node in node_list:
        current_level = node['level']

        tree_node = {
            'title': node['title'],
            'node_id': str(node_counter).zfill(4),
            'text': node['text'],
            'line_num': node['line_num'],
            'nodes': []
        }
        node_counter += 1

        while stack and stack[-1][1] >= current_level:
            stack.pop()

        if not stack:
            root_nodes.append(tree_node)
        else:
            parent_node, parent_level = stack[-1]
            parent_node['nodes'].append(tree_node)

        stack.append((tree_node, current_level))

    return root_nodes
